import json
import os
import sys
import time
from pathlib import Path

import requests

history_id = 'bbd44e69cb8906b5546ddca7e25a7fd1'
base = os.environ['GALAXY_URL'].rstrip('/')
key_path = os.environ['GALAXY_API_KEY_FILE']
with open(key_path, 'r', encoding='utf-8') as handle:
    api_key = handle.read().strip()
headers = {'x-api-key': api_key, 'accept': 'application/json'}
url = 'https://rest.ensembl.org/vep/human/id/rs2136714166?content-type=application/json'
payload = {
    'history_id': history_id,
    'targets': [
        {
            'destination': {'type': 'hdas'},
            'elements': [
                {
                    'src': 'url',
                    'url': url,
                    'ext': 'json',
                    'dbkey': '?',
                    'to_posix_lines': True,
                    'space_to_tab': False,
                    'name': 'Ensembl VEP API rs2136714166 raw JSON',
                }
            ],
        }
    ],
    'auto_decompress': False,
}
resp = requests.post(f'{base}/api/tools/fetch', headers=headers, json=payload, timeout=60)
if resp.status_code >= 400:
    print('SUBMIT_FAILED', resp.status_code, resp.text[:1000])
    sys.exit(1)
submission = resp.json()
Path('galaxy_fetch_submission.json').write_text(json.dumps(submission, indent=2, sort_keys=True), encoding='utf-8')
job_ids = []
for job in submission.get('jobs', []):
    if isinstance(job, dict) and job.get('id'):
        job_ids.append(job['id'])
if not job_ids and submission.get('jobs_summary'):
    jobs_summary = submission['jobs_summary']
    for key in ('jobs', 'job_ids'):
        for job in jobs_summary.get(key, []) if isinstance(jobs_summary, dict) else []:
            if isinstance(job, dict) and job.get('id'):
                job_ids.append(job['id'])
            elif isinstance(job, str):
                job_ids.append(job)
if not job_ids:
    print('NO_JOB_ID', json.dumps(submission)[:1000])
    sys.exit(1)
terminal = {'ok', 'error', 'deleted', 'paused'}
final_jobs = {}
deadline = time.time() + 300
while time.time() < deadline:
    all_terminal = True
    for job_id in job_ids:
        jr = requests.get(f'{base}/api/jobs/{job_id}', headers=headers, timeout=60)
        if jr.status_code >= 400:
            print('JOB_STATUS_FAILED', job_id, jr.status_code, jr.text[:1000])
            sys.exit(1)
        job = jr.json()
        final_jobs[job_id] = job
        if job.get('state') not in terminal:
            all_terminal = False
    if all_terminal:
        break
    time.sleep(10)
else:
    print('WAIT_TIMEOUT', ','.join(job_ids))
    Path('galaxy_fetch_jobs_partial.json').write_text(json.dumps(final_jobs, indent=2, sort_keys=True), encoding='utf-8')
    sys.exit(2)
Path('galaxy_fetch_jobs_final.json').write_text(json.dumps(final_jobs, indent=2, sort_keys=True), encoding='utf-8')
outputs = []
for output in submission.get('outputs', []):
    if isinstance(output, dict):
        outputs.append({'id': output.get('id'), 'name': output.get('name'), 'state': output.get('state'), 'file_ext': output.get('file_ext')})
print(json.dumps({'job_ids': job_ids, 'states': {jid: final_jobs[jid].get('state') for jid in job_ids}, 'outputs': outputs}, sort_keys=True))
if any(final_jobs[jid].get('state') "'!= '"'ok' for jid in job_ids):
    sys.exit(3)
PY"
